-- GenDB engine variant Q07-commuted_comparisons: template q07.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  supp_nation,
  cust_nation,
  l_year,
  SUM(volume) AS revenue
FROM (
  SELECT
    n1.n_name AS supp_nation,
    n2.n_name AS cust_nation,
    EXTRACT(YEAR FROM l_shipdate) AS l_year,
    l_extendedprice * (
      1 - l_discount
    ) AS volume
  FROM supplier, lineitem, orders, customer, nation AS n1, nation AS n2
  WHERE
    l_suppkey = s_suppkey
    AND l_orderkey = o_orderkey
    AND o_custkey = c_custkey
    AND n1.n_nationkey = s_nationkey
    AND n2.n_nationkey = c_nationkey
    AND (
      (
        $1 = n1.n_name AND $2 = n2.n_name
      )
      OR (
        $2 = n1.n_name AND $1 = n2.n_name
      )
    )
    AND l_shipdate BETWEEN CAST('1995-01-01' AS DATE) AND CAST('1996-12-31' AS DATE)
) AS shipping
GROUP BY
  supp_nation,
  cust_nation,
  l_year
ORDER BY
  supp_nation,
  cust_nation,
  l_year
